@extends('layouts.admin') @section('title',__('Sources & automation')) @section('content')<div class="admin-page-heading"><div><p class="eyebrow">{{ __('YOUR CONNECTED NEWSROOM') }}</p><h1>{{ __('Sources & automation') }}<span class="orange">.</span></h1><p>{{ __('Trusted sources. Relevant topics. Fresh perspectives.') }}</p></div><span class="status {{ $aiReady?'published':'draft' }}">{{ $aiReady?__('AI configured'):__('AI key needed') }}</span></div>@unless($aiReady)<div class="alert info">{{ __('Add NEWS_AI_API_KEY to your local .env to enable AI writing. You can manage sources now; imports need an API key and a running queue worker.') }}</div>@endunless<div class="alert info">{{ __('Use a public HTTPS RSS/Atom feed URL, not a website homepage. Only feed-provided article text is imported. Images require your permission confirmation. Start with draft review before enabling auto-publish.') }}</div><div class="settings-columns sources-layout"><div>@forelse($sources as $source)<section class="panel source-card"><div class="panel-heading"><h2>◎ {{ $source->name }}</h2><span class="status {{ $source->enabled?'published':'draft' }}">{{ $source->enabled?__('Active'):__('Paused') }}</span></div><form method="post" action="{{ route('admin.sources.update',$source) }}" class="form-panel">@csrf @method('PUT')@include('admin.source-fields',['source'=>$source])<button class="button secondary">{{ __('Save changes') }}</button></form><div class="source-bottom"><span>{{ __('Last checked') }}: {{ $source->last_checked_at?->diffForHumans() ?: __('Never') }}</span><form method="post" action="{{ route('admin.sources.run',$source) }}">@csrf<button class="text-link">{{ __('Import now') }} ↗</button></form><form method="post" action="{{ route('admin.sources.destroy',$source) }}" data-confirm="{{ __('Delete this source?') }}">@csrf @method('DELETE')<button class="danger-text">{{ __('Delete') }}</button></form></div>@if($source->last_error)<p class="source-error">{{ $source->last_error }}<